def fig_linea():
    fig, ax = plt.subplots(figsize=(7.2, 1.9)); ax.axis("off"); ax.set_xlim(-700, 700); ax.set_ylim(-1.2, 1.4)
    ax.annotate("", xy=(680, 0), xytext=(-680, 0), arrowprops=dict(arrowstyle="<->", color=O, lw=1.6))
    for v in range(-600, 601, 200): ax.plot([v, v], [-.12, .12], color=O); ax.text(v, -.45, ("inicio" if v == 0 else f"{abs(v)} " + ("a.C." if v < 0 else "d.C.")), ha="center", fontsize=8, color=O)
    for v, t in ((-500, "500 a.C."), (200, "200 d.C.")): ax.plot(v, 0, "o", color=V, ms=8); ax.text(v, .45, t, ha="center", fontsize=9, color=V, weight="bold")
    ax.annotate("", xy=(200, .95), xytext=(-500, .95), arrowprops=dict(arrowstyle="<->", color="#c0392b")); ax.text(-150, 1.12, "500 + 200 = 700 años", ha="center", fontsize=9, color="#c0392b", weight="bold")
    return png(fig)
